@startuml

class Person {
  + personID : int
  + phoneNumber : string
  + keywords : string[]
}

class ResearchInstitution {
  + institutionCode : string
}

class ScientificArticle {
  + DOI : string
  + title : string
}

class PeerReviewedPaper extends ScientificArticle {
  + citationCount : int
}

class TechnicalReport extends ScientificArticle {}

class AuthorPosition {
  + position : int
}

class Publisher {
  + name : string
}

class Journal {
  + name : string
  + impactFactor : float
}

Person "1" -- "0..*" ResearchInstitution : works for
Person "1" -- "0..*" ScientificArticle : author
Person "0..*" -- "0..*" ScientificArticle : reviewer
ScientificArticle "1" -- "1..*" AuthorPosition : has
AuthorPosition "0..*" -- "1" Person : relates to
ResearchInstitution "1" -- "0..*" TechnicalReport : publishes
Publisher "1" -- "0..*" Journal : publishes
ResearchInstitution "0..*" -- "0..*" Journal : subscribes
Journal "1" -- "0..*" PeerReviewedPaper : publishes

@enduml

